   356|function resolveSendBranch(
   357|  deliveryBranch: DeliveryBranchStatus['branch'],
   358|  runtimeSource: RuntimeDebugSnapshot['source'],
   359|  httpStatus: string,
   360|): SendBranchProofRow {
   361|  if (deliveryBranch === 'not_observed') {
   362|    return { branch: null, label: 'pending', context: 'no send observed' };
   363|  }
   364|
   365|  const statusFragment = httpStatus !== 'pending' && httpStatus !== 'none' ? ` · ${httpStatus}` : '';
   366|
   367|  if (deliveryBranch === 'remote_db_insert') {
   368|    if (runtimeSource === 'remote_api' || runtimeSource === 'local_app_brain') {
   369|      return { branch: 'primary_realtime', label: 'primary_realtime', context: `assistant db insert${statusFragment}` };
   370|    }
   371|    if (runtimeSource === 'provider_fallback') {
   372|      return { branch: 'alternate_shared', label: 'alternate_shared', context: `gateway db insert${statusFragment}` };
   373|    }
   374|    return { branch: 'primary_realtime', label: 'primary_realtime', context: `db insert · source ${runtimeSource}${statusFragment}` };
   375|  }
   376|
   377|  if (deliveryBranch === 'local_fallback') {
   378|    return { branch: 'snapshot_fallback', label: 'snapshot_fallback', context: `local fallback path${statusFragment}` };
   379|  }
   380|
   381|  if (deliveryBranch === 'auth_session_failure') {
   382|    return { branch: 'local_only', label: 'local_only', context: `auth/session unavailable${statusFragment}` };
   383|  }
   384|
   385|  return { branch: 'local_only', label: 'local_only', context: `unresolved branch${statusFragment}` };
   386|}
